/* @lc app=leetcode id=2435 lang=kotlin */ class Solution { fun numberOfPaths(grid: Array<IntArray>, k: Int): Int = grid.indices.fold(null as Array<IntArray>?) { prev, i -> Array(grid[0].size) { IntArray(k) }.also { cur -> grid[0].indices.forEach { j -> (0 until k).forEach { s -> (((s - grid[i][j]) % k + k) % k).let { t -> cur[j][s] = if (i == 0 && j == 0) (if (s == grid[0][0] % k) 1 else 0) else ((prev?.get(j)?.get(t) ?: 0) + (if (j > 0) cur[j - 1][t] else 0)) % 1_000_000_007 } } } } }!!.last()[0] }